    try:
        if not isinstance(n, int) or not isinstance(qid, int):
            raise ValueError("Parameters n and qid must be integers.")

        if n < -1 or qid < -1:
            raise ValueError("Parameters n and qid must be -1 or greater.")

        msg = {
            "CREDENTIALS": {
                "n": n,
                "qid": qid
            }
        }

