def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    import sys
    from multiprocessing import Pool
    from io import BytesIO

    def _run_cmd(args):
        try:
            full_cmd = cmd + (args,)
            result = subprocess.run(full_cmd, capture_output=True, check=True, text=False, **kwargs)
            return (result.returncode, result.stdout)
        except subprocess.CalledProcessError as e:
            return (e.returncode, e.stdout + e.stderr)

    if not cmd:
        raise ValueError("cmd cannot be empty")
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not isinstance(varargs, (list, tuple)):
        raise TypeError("varargs must be a list or tuple")

    if color and os.name == 'posix':
        kwargs['stdout'] = subprocess.PIPE
        kwargs['stderr'] = subprocess.PIPE
        kwargs['universal_newlines'] = False
    else:
        kwargs['stdout'] = subprocess.PIPE
        kwargs['stderr'] = subprocess.PIPE
        kwargs['text'] = False

    # Split varargs into chunks for each process
    chunks = [varargs[i::target_concurrency] for i in range(target_concurrency)]
    results = []

    with Pool(processes=target_concurrency) as pool:
        for chunk in chunks:
            results.extend(pool.map(_run_cmd, chunk))

    final_output = BytesIO()
    return_code = 0

    for code, output in results:
        final_output.write(output)
        if code != 0:
            return_code = code

    return return_code, final_output.getvalue()

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor
    from itertools import islice

    def chunked(it, n):
        it = iter(it)
        while True:
            chunk = tuple(islice(it, n))
            if not chunk:
                return
            yield chunk

    def run_command(chunk):
        full_cmd = cmd + tuple(chunk)
        try:
            result = subprocess.run(
                full_cmd,
                check=False,
                color=color and os.name == 'posix',
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                **kwargs
            )
            return result.returncode, result.stdout + result.stderr
        except Exception as e:
            return 1, str(e).encode()

    all_results = []
    return_code = 0

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_chunk = {executor.submit(run_command, chunk): chunk for chunk in chunked(varargs, _max_length // len(cmd))}
        for future in future_to_chunk:
            try:
                rc, output = future.result()
                all_results.append(output)
                if rc != 0:
                    return_code = rc
            except Exception as exc:
                all_results.append(str(exc).encode())
                return_code = 1

    return return_code, b''.join(all_results)

