def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seen = set()
        result = []
        for cls in classes:
            if cls not in seen:
                is_redundant = False
                for other in classes:
                    if cls != other and issubclass(cls, other):
                        is_redundant = True
                        break
                if not is_redundant:
                    result.append(cls)
                    seen.add(cls)
        return result
    except Exception as e:
        raise ValueError(f"An error occurred while reducing base classes: {e}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []
    for cls in classes:
        if cls not in seen:
            minimal.append(cls)
            seen.add(cls)
            seen.update(cls.__bases__)
    return [cls for cls in classes if all(base not in cls.__mro__ for base in seen if base is not cls)]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to store unique minimal base classes
        minimal_bases = set()
        # Create a set to store all bases for comparison
        all_bases = set()

        # Collect all base classes and their parent bases
        for cls in classes:
            all_bases.update(cls.__mro__)

        # Determine minimal bases by checking which classes are not a subclass of any other class in the list
        for cls in classes:
            if all(not issubclass(cls, other) for other in classes if cls is not other):
                minimal_bases.add(cls)

        # Return the minimal bases in the order they appear in the original list
        return [cls for cls in classes if cls in minimal_bases]

    except Exception as e:
        raise ValueError(f"An error occurred while determining minimal bases: {str(e)}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if not any(issubclass(c, cls) for c in minimal):
            minimal.append(cls)
            minimal = [c for c in minimal if not issubclass(cls, c)]
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        minimal_classes = []
        for cls in classes:
            if cls not in minimal_classes:
                if not any(issubclass(c, cls) for c in classes):
                    minimal_classes.append(cls)
                else:
                    for c in minimal_classes[:]:
                        if issubclass(c, cls):
                            minimal_classes.remove(c)
                    minimal_classes.append(cls)
        return minimal_classes
    except TypeError as e:
        raise ValueError("All elements in the list must be class types") from e

