def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    from typing import TypeVar, cast

    T = TypeVar('T', str, bytes)

    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a str or bytes")

    if not isinstance(params, (dict, list, tuple)):
        raise ValueError("params must be a dict, list, or tuple")

    if self.SQLParams.in_style in ['named', 'pyformat', 'format']:
        if not isinstance(params, dict):
            raise ValueError("params must be a dict for named parameter styles")

        out_params = {}
        param_names = list(params.keys())
        param_values = list(params.values())

        for i, name in enumerate(param_names):
            out_params[i + 1] = param_values[i]

        if isinstance(sql, str):
            formatted_sql = sql % tuple(['%s'] * len(param_names))
        else:
            formatted_sql = sql % tuple([b'%s'] * len(param_names))

    elif self.SQLParams.in_style in ['qmark', 'numeric', 'ordinal']:
        if not isinstance(params, (list, tuple)):
            raise ValueError("params must be a list or tuple for ordinal parameter styles")

        out_params = {i + 1: value for i, value in enumerate(params)}
        formatted_sql = sql

    else:
        raise ValueError(f"Unsupported in_style: {self.SQLParams.in_style}")

    return cast(Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]], (formatted_sql, out_params))

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    try:
        if isinstance(params, collections.abc.Mapping):
            # Assuming named parameters
            out_params = {self._convert_param_name(k): v for k, v in params.items()}
            formatted_sql = sql % out_params if self.SQLParams.out_style == 'pyformat' else sql
            return formatted_sql, out_params
        elif isinstance(params, collections.abc.Sequence):
            # Assuming positional parameters
            out_params = [self._convert_param_value(p) for p in params]
            placeholders = {i: p for i, p in enumerate(out_params)}
            formatted_sql = sql % placeholders if self.SQLParams.out_style == 'pyformat' else sql
            return formatted_sql, out_params
        else:
            raise TypeError("Params must be a Mapping or Sequence.")
    except Exception as e:
        raise ValueError(f"Error formatting SQL query: {str(e)}")

def _convert_param_name(self, name: Union[str, int]) -> Union[str, int]:
    # Example conversion, can be customized
    if self.SQLParams.out_style == 'pyformat':
        return f"%({name})s"
    elif self.SQLParams.out_style == 'qmark':
        return "?"
    elif self.SQLParams.out_style == 'numeric':
        return f":{name}"
    elif self.SQLParams.out_style == 'named':
        return f":{name}"
    elif self.SQLParams.out_style == 'format':
        return f"%s"
    else:
        raise ValueError(f"Unsupported out-style: {self.SQLParams.out_style}")

def _convert_param_value(self, value: Any) -> Any:
    # Example conversion, can be customized
    return value

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    try:
        out_style_params = []
        if self.SQLParams.in_style == 'named':
            # Assuming out_style is qmark for demonstration
            for params in many_params:
                if not isinstance(params, Mapping):
                    raise ValueError("Params must be a Mapping for named in-style parameters.")
                converted_params = []
                for param in sql:
                    if isinstance(param, str) and param.startswith(':'):
                        key = param[1:]
                        if key in params:
                            converted_params.append(params[key])
                            sql = sql.replace(param, '?', 1)
                out_style_params.append(converted_params)
        elif self.SQLParams.in_style == 'ordinal':
            # Assuming out_style is pyformat for demonstration
            for params in many_params:
                if not isinstance(params, Sequence):
                    raise ValueError("Params must be a Sequence for ordinal in-style parameters.")
                converted_params = {}
                for i, param in enumerate(params):
                    key = f'%({i})s'
                    sql = sql.replace('?', key, 1)
                    converted_params[i] = param
                out_style_params.append(converted_params)
        else:
            raise ValueError("Unsupported in-style parameter type.")
        return sql, out_style_params
    except Exception as e:
        raise ValueError(f"Error formatting SQL query: {e}")

