def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    from os.path import basename, splitext

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    package_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = splitext(basename(file_info.filename))[0]
                    if base_name not in package_data:
                        package_data[base_name] = []
                    with z.open(file_info) as file:
                        package_data[base_name].append(file.read())
    except zipfile.BadZipFile:
        raise ValueError("Invalid zip file")
    except FileNotFoundError:
        raise FileNotFoundError("Zip file not found")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

    return package_data

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    from os.path import basename, splitext

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            xml_data = {}
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = splitext(basename(file_info.filename))[0]
                    with z.open(file_info) as file:
                        content = file.read()
                        if base_name in xml_data:
                            xml_data[base_name].append(content)
                        else:
                            xml_data[base_name] = [content]
            return xml_data
    except (zipfile.BadZipFile, FileNotFoundError) as e:
        print(f"Error reading zip file {zip_path}: {e}")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

