def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        indent_str = "  " * indent
        output = f"{indent_str}{self.__class__.__name__}("
        if debug:
            output += f"id={getattr(self, 'id', 'None')}, "
        if hasattr(self, 'attributes'):
            output += f"attributes={self.attributes}, "
        if hasattr(self, 'children') and self.children:
            output += f"\n{indent_str}  children=[\n"
            for child in self.children:
                output += child.pretty(indent + 2, debug) + ",\n"
            output += f"{indent_str}  ]"
        output += ")"
        return output
    except Exception as e:
        return f"{indent_str}Error printing: {e}"

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        indent_str = '  ' * indent
        repr_str = indent_str + self.__class__.__name__ + '('
        if debug:
            repr_str += f'id={self.id}, ' if hasattr(self, 'id') else ''
        for attr, value in self.__dict__.items():
            if not attr.startswith('_'):
                repr_str += f'{attr}={value}, '
        repr_str = repr_str.rstrip(', ') + ')\n'
        if hasattr(self, '__iter__'):
            for item in self:
                if hasattr(item, 'pretty'):
                    repr_str += item.pretty(indent + 1, debug)
        return repr_str
    except Exception as e:
        return f"{indent_str}Error formatting object: {str(e)}\n"

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_string = '  ' * indent
    result = f"{indent_string}{self.__class__.__name__}("
    if debug:
        result += f"id={getattr(self, 'id', None)}, "
    result += ")\n"
    for key, value in sorted(self.__dict__.items()):
        if key.startswith('_') or key in ['doc', 'parent']:
            continue
        if isinstance(value, list):
            result += f"{indent_string}  {key}:\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    result += item.pretty(indent + 2, debug)
                else:
                    result += f"{indent_string}    {item}\n"
        elif hasattr(value, 'pretty'):
            result += f"{indent_string}  {key}:\n"
            result += value.pretty(indent + 2, debug)
        else:
            result += f"{indent_string}  {key}={value}\n"
    return result

def pretty(self, indent=0, debug=False):
    """
