    try:
        indent_str = '  ' * indent
        if debug:
            additional_info = f' (id={self.id})' if hasattr(self, 'id') else ''
            return f"{indent_str}{self.__class__.__name__}{additional_info}"
        return f"{indent_str}{self.__class__.__name__}"
    except Exception as e:
        return f"{indent_str}Error: {str(e)}"

