    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections.abc import Iterable
    if not isinstance(args, Iterable):
        raise ValueError("args must be an iterable of expressions")

    simplified_args = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == (('|', left, object()) or ('|', object(), left)):
                    simplified_args.append(left)
                elif right == (('&', ('~', left, None), object()) or ('&', object(), ('~', left, None))):
                    simplified_args.append(('&', left, right[1] if right[0] == '&' and right[1] != ('~', left, None) else right[2]))
            elif op == '|':
                if right == (('&', left, object()) or ('&', object(), left)):
                    simplified_args.append(left)
                elif right == (('|', ('~', left, None), object()) or ('|', object(), ('~', left, None))):
                    simplified_args.append(('|', left, right[1] if right[0] == '|' and right[1] != ('~', left, None) else right[2]))
            else:
                simplified_args.append(expr)
        else:
            simplified_args.append(expr)
    return simplified_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op = expr[0]
        a, b = expr[1], expr[2]

        # Absorption laws
        if op == '&' and isinstance(b, tuple) and b[0] == '|':
            if a == b[1] or a == b[2]:
                return a
        if op == '|' and isinstance(b, tuple) and b[0] == '&':
            if a == b[1] or a == b[2]:
                return a
        if op == '&' and isinstance(a, tuple) and a[0] == '|':
            if b == a[1] or b == a[2]:
                return b
        if op == '|' and isinstance(a, tuple) and a[0] == '&':
            if b == a[1] or b == a[2]:
                return b

        # Negative absorption laws
        if op == '&' and isinstance(b, tuple) and b[0] == '|':
            if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                return ('&', a, b[2])
            if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                return ('&', a, b[1])
        if op == '|' and isinstance(b, tuple) and b[0] == '&':
            if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                return ('|', a, b[2])
            if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                return ('|', a, b[1])
        if op == '&' and isinstance(a, tuple) and a[0] == '|':
            if isinstance(a[1], tuple) and a[1][0] == '~' and a[1][1] == b:
                return ('&', b, a[2])
            if isinstance(a[2], tuple) and a[2][0] == '~' and a[2][1] == b:
                return ('&', b, a[1])
        if op == '|' and isinstance(a, tuple) and a[0] == '&':
            if isinstance(a[1], tuple) and a[1][0] == '~' and a[1][1] == b:
                return ('|', b, a[2])
            if isinstance(a[2], tuple) and a[2][0] == '~' and a[2][1] == b:
                return ('|', b, a[1])

        # Recursively apply absorption to sub-expressions
        if isinstance(a, tuple):
            a = apply_absorption(a)
        if isinstance(b, tuple):
            b = apply_absorption(b)

        return (op, a, b)

    return [apply_absorption(expr) for expr in args]

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Expected a callable, got {type(func)} instead")
        if not hasattr(self, 'registry'):
            self.registry = {}
        if hook not in self.registry:
            self.registry[hook] = []
        self.registry[hook].append(func)
        return func
    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    if not isinstance(user, str):
        raise ValueError("User must be a string.")
    if not isinstance(etcd_host, str):
        raise ValueError("Etcd host must be a string.")
    if not isinstance(etcd_port, int):
        raise ValueError("Etcd port must be an integer.")
    if etcd_port <= 0:
        raise ValueError("Etcd port must be a positive integer.")

    config = {
        'user': user,
        'etcd': {
            'host': etcd_host,
            'port': etcd_port
        }
    }
    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        return [name.encode('ascii') if isinstance(name, unicode) else name for name in namefunc()]
    except NameError:  # unicode is not defined in Python 3
        return namefunc()

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import sys
        if sys.version_info[0] < 3:
            return [name.encode('utf-8') for name in namefunc()]
        else:
            return namefunc()
    except Exception as e:
        raise RuntimeError("Error in tzname_in_python2: %s" % e)

def tzname_in_python2(namefunc):
