def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        args = [args]

    full_command = commands + args

    if verbose:
        print("Running command:", ' '.join(full_command))

    try:
        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, error = process.communicate()
            if process.returncode != 0:
                if verbose:
                    print("Command failed with return code:", process.returncode)
                if hide_stderr and error:
                    print("Error:", error)
                raise subprocess.CalledProcessError(returncode=process.returncode, cmd=full_command, output=output, stderr=error)
            if verbose:
                print("Command output:", output)
            return output
    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {commands[0]}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
