    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs or not isinstance(version_dirs, list):
        raise ValueError("version_dirs should be a non-empty list of version directory names.")

    root_inventory = {}
    try:
        with open(os.path.join(self.root_directory, 'inventory.json'), 'r') as f:
            root_inventory = json.load(f)
    except FileNotFoundError:
        print("Root inventory not found.")
    except json.JSONDecodeError:
        print("Root inventory is not a valid JSON file.")
    except Exception as e:
        print(f"An error occurred while reading the root inventory: {e}")

    differing_content_digests = {}

    for version_dir in version_dirs:
        version_path = os.path.join(self.root_directory, version_dir)
        inventory_path = os.path.join(version_path, 'inventory.json')

        if not os.path.exists(version_path):
            print(f"Version directory {version_dir} does not exist.")
            continue

        if not os.path.exists(inventory_path):
            print(f"Inventory file not found for version {version_dir}.")
            continue

        try:
            with open(inventory_path, 'r') as f:
                version_inventory = json.load(f)
