            continue
        except Exception as e:
            print(f"An error occurred while reading the inventory for version {version_dir}: {e}")
            continue

        for content_id, content_info in version_inventory.items():
            root_digest = root_inventory.get(content_id, {}).get('digest')
            version_digest = content_info.get('digest')

            if root_digest and version_digest and root_digest != version_digest:
                differing_content_digests[content_id] = {
                    'root_digest': root_digest,
                    'version_digest': version_digest
                }

    return differing_content_digests

