def parse_arguments(*unparsed_arguments):
    '''Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser(description='Parse command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example global arguments
    parser.add_argument('--verbosity', type=int, help='Increase output verbosity')

    # Example subparsers
    subparser_a = subparsers.add_parser('a', help='Subparser A')
    subparser_a.add_argument('foo', type=str, help='Foo argument for subparser A')

    subparser_b = subparsers.add_parser('b', help='Subparser B')
    subparser_b.add_argument('bar', type=int, help='Bar argument for subparser B')

    try:
        parsed = parser.parse_args(unparsed_arguments)
        result = {}

        if parsed.subparser_name is None:
            result['global'] = parsed
        else:
            result['global'] = argparse.Namespace(verbosity=parsed.verbosity)
            result[parsed.subparser_name] = parsed

        return result

    except argparse.ArgumentError as e:
        print(e)
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

