    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    merged = defaultdict(list)

    for key, value in nodes:
        key_value = key.value
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            existing_value = merged[key_value]
            existing_dict = {}
            for k, v in existing_value:
                existing_dict[k.value] = (k, v)
            for k, v in value.value:
                existing_dict[k.value] = (k, v)
            merged[key_value] = list(existing_dict.values())
        else:
            merged[key_value] = [(key, value)]

    return [(key_node, ruamel.yaml.nodes.MappingNode(tag=value[0][1].tag, value=[item for item in val])) for key_node, val in merged.items()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def merge_values(key, v1, v2):
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            merged_mapping = {}
            v1_map = {k.value: v for k, v in v1.value}
            v2_map = {k.value: v for k, v in v2.value}
            merged_keys = set(v1_map.keys()).union(set(v2_map.keys()))
            for k in merged_keys:
                if k in v1_map and k in v2_map:
                    merged_mapping[k] = merge_values(k, v1_map[k], v2_map[k])
                elif k in v1_map:
                    merged_mapping[k] = v1_map[k]
                else:
                    merged_mapping[k] = v2_map[k]
            return MappingNode(v1.tag, list(merged_mapping.items()), start_mark=v1.start_mark, end_mark=v1.end_mark)
        else:
            return v2

    merged_nodes = {}
    for key_node, value_node in nodes:
        key_value = key_node.value
        if key_value in merged_nodes:
            merged_nodes[key_value] = merge_values(key_node, merged_nodes[key_value], value_node)
        else:
            merged_nodes[key_value] = value_node

    return [(ScalarNode(key_node.tag, k), v) for k, v in merged_nodes.items()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    def merge_mapping(target, source):
        for key, value in source.value:
            key_value = key.value
            if key_value in target:
                if isinstance(target[key_value][1], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                    merge_mapping(target[key_value][1], value)
                else:
                    target[key_value] = (key, value)
            else:
                target[key_value] = (key, value)

    merged_dict = defaultdict(tuple)
    for key, value in nodes:
        key_value = key.value
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            if key_value in merged_dict:
                merge_mapping(merged_dict[key_value][1], value)
            else:
                merged_dict[key_value] = (key, value)
        else:
            merged_dict[key_value] = (key, value)

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    merged = defaultdict(lambda: None)

    def merge_key_value(key, value):
        key_value = (key.tag, key.value)
        if key_value in merged:
            if isinstance(merged[key_value], list) and isinstance(value, list):
                # Both are MappingNodes, merge their contents
                merged_dict = defaultdict(lambda: None)
                for k, v in merged[key_value] + value:
                    merge_key_value(k, v)
                    merged[key_value] = list(merged_dict.items())
            else:
                # Last value wins in case of non-MappingNode or mixed types
                merged[key_value] = value
        else:
            merged[key_value] = value

    for key, value in nodes:
        if isinstance(value, list):
            # Assuming MappingNode is represented as a list of tuples
            merged_dict = defaultdict(lambda: None)
            for k, v in value:
                merge_key_value(k, v)
            merged[(key.tag, key.value)] = list(merged_dict.items())
        else:
            merge_key_value(key, value)

    return [(ScalarNode(tag=k[0], value=k[1]), v) for k, v in merged.items()]

