def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import inspect
    from borgmatic.commands import arguments

    def get_command_name(parser):
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for key in action.choices:
                    return key
        return parser.prog.split(' ')[-1]

    def get_command_arguments(parser):
        arguments = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for choice in action.choices:
                    arguments.extend(get_command_arguments(action.choices[choice]))
            elif action.option_strings:
                arguments.extend(action.option_strings)
        return arguments

    def generate_completion_script(parser):
        command_name = get_command_name(parser)
        command_arguments = get_command_arguments(parser)
        script = f"_borgmatic_{command_name}() {{
            local cur prev opts
            COMPREPLY=()
            cur=\"{{COMP_WORDS[COMP_CWORD]}\}"
            prev=\"{{COMP_WORDS[COMP_CWORD-1]}\}"
            opts=\"{' '.join(command_arguments)}\"
            COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )
            return 0
            }}
            complete -F _borgmatic_{command_name} borgmatic"

        return script

    main_parser = arguments.create_argument_parser()
    return generate_completion_script(main_parser)

def bash_completion():
    '''
