    def _generate_command_completion(command, parser):
        """Generate bash completion for a given command and its parser."""
        completions = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subcommand, subparser in action.choices.items():
                    completions.extend(_generate_command_completion(f"{command} {subcommand}", subparser))
            elif action.option_strings:
                completions.extend(action.option_strings)
        return f"complete -W \"{' '.join(completions)}\" {command}\n"

    try:
