        print("borgmatic is not installed or not importable.", file=sys.stderr)
        return

    completion_script = _generate_command_completion("borgmatic", borgmatic_args)
    return completion_script

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser setup
    # subparser1 = subparsers.add_parser('subcommand1', help='Help for subcommand1')
