def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments[:]

    for subparser_name, parser in subparsers.items():
        try:
            namespace, extra_args = parser.parse_known_args(unparsed_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = extra_args
            unparsed_arguments = extra_args
        except Exception as e:
            # If parsing fails, we skip to the next subparser
            continue

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        try:
            parsed_namespace, remaining = subparser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = parsed_namespace
            remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, continue to the next subparser
            continue

    return parsed_arguments, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.strip()
        suffix = size[-1].upper()
        num = float(size[:-1]) if suffix.isalpha() else float(size)

        if suffix == 'K':
            return int(num * 1000)
        elif suffix == 'M':
            return int(num * 1000 * 1000)
        elif suffix == 'G':
            return int(num * 1000 * 1000 * 1000)
        elif suffix == 'T':
            return int(num * 1000 * 1000 * 1000 * 1000)
        elif suffix == 'P':
            return int(num * 1000 * 1000 * 1000 * 1000 * 1000)
        else:
            return int(num)
    except (ValueError, IndexError, TypeError):
        raise ValueError(f"Invalid size format: {size}")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

