def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not alphabet or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a non-empty list of strings.")

    base = len(alphabet)
    if base < 1:
        raise ValueError("Alphabet must contain at least one character.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None and len(digits) < padding:
        digits.extend(alphabet[0] * (padding - len(digits)))

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if number < 0:
        raise ValueError("Number must be non-negative")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None:
        digits += [alphabet[0]] * (padding - len(digits))

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None and padding > len(digits):
        digits.extend(alphabet[0] * (padding - len(digits)))

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
