def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses_list = list(cls.__subclasses__())
    for subclass in list(subclasses_list):
        subclasses_list.extend(subclasses(subclass))
    return subclasses_list

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses_list = []

    def _subclasses(current_cls):
        for subclass in current_cls.__subclasses__():
            subclasses_list.append(subclass)
            _subclasses(subclass)

    _subclasses(cls)
    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    base = len(alphabet)
    result = 0
    try:
        for index, char in enumerate(reversed(string)):
            digit = alphabet.index(char)
            result += digit * (base ** index)
    except ValueError:
        raise ValueError(f"Character '{char}' is not in the provided alphabet.")
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    base = len(alphabet)
    result = 0

    for char in string:
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"Character '{char}' not found in the alphabet.")

        result = result * base + digit

    return result

