        raise ValueError("Unsupported platform value. Use 'this', 0, or 1.")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import os

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX
        # POSIX shell-like syntax
        regex = r'''(?:"([^"]*)")|('([^']*)')|(\S+)'''
    elif platform == 0:  # Windows/CMD
        # Windows CMD-like syntax (simplified)
        regex = r'''(?:"([^"]*)")|(\S+)'''
    else:
        raise ValueError("Invalid platform value")

    args = []
    for match in re.finditer(regex, s):
        if match.group(1):
            args.append(match.group(1))
        elif match.group(2):
            args.append(match.group(2))
        elif match.group(3):
            args.append(match.group(3))
        elif match.group(4):
            args.append(match.group(4))

    return args

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path

    if filename is None:
        filename = Path(archive_path).stem

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)

    repo_path = tmp_path / filename
    repo_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.zip'):
            shutil.unpack_archive(archive_path, repo_path)
        elif archive_path.endswith(('.tar', '.tar.gz', '.tgz', '.tar.bz2', '.tbz2')):
            subprocess.run(['tar', '-xf', archive_path, '-C', repo_path], check=True)
        else:
            raise ValueError("Unsupported archive format")
    except Exception as e:
        shutil.rmtree(repo_path, ignore_errors=True)
        raise RuntimeError(f"Failed to extract archive: {e}")

    return repo_path.resolve().as_uri()

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)

    if filename:
        extract_path = tmp_path / filename
    else:
        extract_path = tmp_path / Path(archive_path).stem

    try:
        if archive_path.endswith(('.zip', '.ZIP')):
            subprocess.run(['unzip', archive_path, '-d', str(extract_path)], check=True)
        elif archive_path.endswith(('.tar.gz', '.tgz', '.tar', '.gz')):
            subprocess.run(['tar', '-xzvf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.bz2'):
            subprocess.run(['tar', '-xjvf', archive_path, '-C', str(tmp_path)], check=True)
        else:
            raise ValueError("Unsupported archive format")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error extracting archive {archive_path}: {e}")

    return f"file://{extract_path}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    try:
        tmp_path = Path(tmp_path)
        tmp_path.mkdir(parents=True, exist_ok=True)

        if not filename:
            filename = Path(archive_path).name

        extract_cmd = None
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            extract_cmd = ['tar', '-xzf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.zip'):
            extract_cmd = ['unzip', '-q', archive_path, '-d', str(tmp_path)]
        elif archive_path.endswith('.tar.bz2'):
            extract_cmd = ['tar', '-xjf', archive_path, '-C', str(tmp_path)]
        else:
            raise ValueError("Unsupported archive type")

        subprocess.run(extract_cmd, check=True)

        # Assuming the archive contains a single directory or file which is the repository
        contents = list(tmp_path.iterdir())
        if len(contents) == 1 and contents[0].is_dir():
            repo_path = contents[0]
        elif len(contents) == 1 and contents[0].is_file():
            repo_path = contents[0]
        else:
            raise ValueError("Archive does not contain a single directory or file")

        return f"file://{repo_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    if not isinstance(tmp_path, Path):
        tmp_path = Path(tmp_path)

    if not tmp_path.exists():
        tmp_path.mkdir(parents=True, exist_ok=True)

    try:
        if filename is None:
            filename = os.path.basename(archive_path)

        tmp_repo_path = tmp_path / filename
        subprocess.run(['tar', '-xzf', archive_path, '-C', str(tmp_path)], check=True)
        return f"file://{tmp_repo_path}"
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        # Run git ls-files --others --ignored --exclude-from=ignored
        result = subprocess.run(['git', 'ls-files', '--others', '--ignored', '--exclude-from=' + ignored], capture_output=True, text=True, check=True)
        # Split the output into a list of file names
        files = result.stdout.splitlines()
        # Return the files as a single string separated by commas
        return ','.join(files)
    except subprocess.CalledProcessError as e:
        print(f"Error executing git command: {e}")
        return ''
    except Exception as e:
        print(f"An error occurred: {e}")
        return ''

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    # Split the frequency into number and unit
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency}")

    try:
        count = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {frequency}")

    unit = parts[1].lower().rstrip('s')  # Remove plural form if present
    if unit == "week":
        return datetime.timedelta(weeks=count)
    elif unit == "day":
        return datetime.timedelta(days=count)
    elif unit == "hour":
        return datetime.timedelta(hours=count)
    elif unit == "minute":
        return datetime.timedelta(minutes=count)
    elif unit == "second":
        return datetime.timedelta(seconds=count)
    else:
        raise ValueError(f"Unknown time unit in frequency: {frequency}")

