        count = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {frequency}")

    unit = parts[1].strip().lower()
    if unit == "second" or unit == "seconds":
        return datetime.timedelta(seconds=count)
    elif unit == "minute" or unit == "minutes":
        return datetime.timedelta(minutes=count)
    elif unit == "hour" or unit == "hours":
        return datetime.timedelta(hours=count)
    elif unit == "day" or unit == "days":
        return datetime.timedelta(days=count)
    elif unit == "week" or unit == "weeks":
        return datetime.timedelta(weeks=count)
    elif unit == "month":
        # Approximation, as months have different numbers of days
        return datetime.timedelta(days=count * 30)
    elif unit == "year":
        # Approximation, as years have different numbers of days
        return datetime.timedelta(days=count * 365)
    else:
        raise ValueError(f"Unknown time unit in frequency: {frequency}")

