def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    try:
        if not overwrite and os.path.exists(config_filename):
            return

        os.makedirs(os.path.dirname(config_filename), exist_ok=True)
        with open(config_filename, 'w', mode=mode) as f:
            f.write(rendered_config)
    except IOError as e:
        raise IOError(f"Failed to write configuration file '{config_filename}': {e}") from e
    except PermissionError as e:
        raise PermissionError(f"Permission denied when writing configuration file '{config_filename}': {e}") from e
    except Exception as e:
        raise Exception(f"An error occurred while writing configuration file '{config_filename}': {e}") from e

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: The script to be converted
    :return: A one-liner version of the script
    """
    try:
        lines = script.strip().splitlines()
        filtered_lines = [line for line in lines if line.strip() and not line.strip().startswith('#')]
        return seperator.join(filtered_lines)
    except Exception as e:
        raise ValueError(f"An error occurred while converting script to one line: {e}")

