def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred during Gaussian calculation: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configurations = {}
    errors = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
            if resolve_env:
                for section in config.sections():
                    for key in config[section]:
                        config[section][key] = os.path.expandvars(config[section][key])
            configurations[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                       msg=str(e), args=(), exc_info=True)
            errors.append(record)

    # Apply overrides
    for section, key_values in overrides.items():
        if section not in configurations:
            configurations[section] = {}
        configurations[section].update(key_values)

    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import configparser

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)
                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            config[section][key] = os.path.expandvars(value)
                config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=None,
                exc_info=True
            )
            log_records.append(record)

    # Apply overrides
    for key, value in overrides.items():
        section, option = key.split(':')
        for config in config_dict.values():
            if config.has_section(section) and config.has_option(section, option):
                config.set(section, option, value)
                break

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import json
    import os

    if not overrides:
        overrides = {}

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config = json.load(file)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=config_filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(record)
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[config_filename] = {**config, **overrides}

    return config_dict, log_records

