def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import Invalid, providedBy
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not provide the interface {iface}")

    for name, spec in iface.namesAndDescriptions():
        if spec.getTaggedValue('readonly', False) and isinstance(spec, iface.Attribute):
            continue  # Skip read-only attributes as they are not required to be set
        if isinstance(spec, iface.Attribute):
            if not hasattr(candidate, name):
                errors.append(f"Attribute '{name}' is not defined")
        elif isinstance(spec, iface.Method):
            if not hasattr(candidate, name):
                errors.append(f"Method '{name}' is not defined")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Attribute '{name}' is not callable")
                else:
                    sig = inspect.signature(method)
                    try:
                        sig.bind_partial(*spec.getBases())  # bind_partial allows for default arguments
                    except TypeError as e:
                        errors.append(f"Method '{name}' has an incorrect signature: {e}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import providedBy, Invalid
    from inspect import signature, Parameter

    errors = []

    # Step 1: Check if the candidate provides the interface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface.__name__}.")

    # Step 2 and 3: Check methods and their signatures
    for name, attribute in iface.namesAndDescriptions():
        if vtype is not None and not isinstance(attribute, vtype):
            continue
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define method/attribute '{name}'.")
            continue
        attr = getattr(candidate, name)
        if callable(attr):
            try:
                sig = signature(attr)
                for param in sig.parameters.values():
                    if param.kind == Parameter.VAR_POSITIONAL:
                        continue
                    if param.kind == Parameter.VAR_KEYWORD:
                        continue
                required_params = [param.name for param in sig.parameters.values() if param.default == Parameter.empty]
                if len(required_params) > len(getattr(attribute, '__args__', [])) and not hasattr(attribute, '__args__'):
                    errors.append(f"Candidate's method '{name}' does not match the required parameters of the interface method.")
            except ValueError:
                continue

    # Step 4: Check attributes
    for name, attribute in iface.namesAndDescriptions():
        if vtype is not None and not isinstance(attribute, vtype):
            continue
        if callable(getattr(candidate, name, None)):
            continue
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define attribute '{name}'.")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

