        r'(?:%[0-9a-fA-F][0-9a-fA-F]))+'  # ...percent-encoded chars
    )

    try:
        processed_text = url_pattern.sub(linkify, text)
        return processed_text
    except Exception as e:
        print(f"An error occurred: {e}")
        return text

