def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Attempt to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Attempt to parse as XRD (XML)
            root = ET.fromstring(document)
            xmlns = {'xrds': 'xri://$xrds'}
            xrd_element = root.find('xrds:XRD', xmlns)
            if xrd_element is None:
                raise ValueError("Invalid XRD format: Missing XRD element")

            result = {}
            for link in xrd_element.findall('xrds:Link', xmlns):
                attributes = link.attrib
                rel = attributes.get('rel')
                if rel is not None:
                    result[rel] = {k: v for k, v in attributes.items() if k != 'rel'}

            return result
        except ET.ParseError:
            raise ValueError("Document is neither valid JSON nor valid XRD (XML)")

