def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree as ET

    if not isinstance(handle, str) or not handle.strip():
        raise ValueError("Handle must be a non-empty string.")

    try:
        response = requests.get(f'https://diaspora/{handle}/.well-known/webfinger', params={'resource': f'acct:{handle}'})
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError as e:
        raise Exception(f"Failed to parse webfinger document: {e}")

    webfinger_data = {}
    for elem in root.findall('.//{http://xmlns.jabber.org/protocol/disco#info}identity'):
        category = elem.attrib.get('category')
        type = elem.attrib.get('type')
        name = elem.attrib.get('name')
        if category and type:
            webfinger_data['identity'] = {'category': category, 'type': type, 'name': name}

    for elem in root.findall('.//{http://xmlns.jabber.org/protocol/disco#info}link'):
        rel = elem.attrib.get('rel')
        template = elem.attrib.get('template')
        href = elem.attrib.get('href')
        if rel and (template or href):
            if rel not in webfinger_data:
                webfinger_data[rel] = []
            webfinger_data[rel].append({'template': template, 'href': href})

    return webfinger_data

